type Item = { id: string; name: string };

function Cart() {
  const [items, setItems] = useState<Item[]>([]);
  const [log, setLog] = useState<string[]>([]);

  async function addSelected(ids: string[]) {
    const picked = await fetchItems(ids);
    picked.forEach((item) => {
      setItems([...items, item]);
      setLog((entries) => [...entries, `added ${item.id}`]);
    });
  }

  return (
    <div>
      <button onClick={() => addSelected(['a', 'b', 'c'])}>Add three</button>
      <ul>{items.map((item) => <li key={item.id}>{item.name}</li>)}</ul>
      <pre>{log.join('\n')}</pre>
    </div>
  );
}

